import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.DBKUV7en.js";const c=JSON.parse('{"title":"2. 基準の一杯(最初のレシピと、その理由)","description":"","frontmatter":{},"headers":[],"relativePath":"basics/base-recipe.md","filePath":"basics/base-recipe.md","lastUpdated":null}'),s={name:"basics/base-recipe.md"};function i(n,t,l,p,o,h){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="_2-基準の一杯-最初のレシピと、その理由" tabindex="-1">2. 基準の一杯(最初のレシピと、その理由) <a class="header-anchor" href="#_2-基準の一杯-最初のレシピと、その理由" aria-label="Permalink to &quot;2. 基準の一杯(最初のレシピと、その理由)&quot;">​</a></h1><p>何グラムの粉に、何グラムのお湯を注ぐのか。何度で、何秒か。ドリップを始めたときに、最初に困るのがここです。</p><p>この教科書では、次の一杯を<strong>基準</strong>にします。正解ではなく、1回に1つだけ変えるための、動かさない土台です。この回は、抽出の話の出発点です。</p><table tabindex="0"><thead><tr><th>項目</th><th>基準</th></tr></thead><tbody><tr><td>粉</td><td>15g</td></tr><tr><td>お湯</td><td>240g(比率 約1:16)</td></tr><tr><td>湯温</td><td>92℃(ケトルで測る)</td></tr><tr><td>蒸らし</td><td>粉の約2〜3倍のお湯(30〜45g)を注いで、30〜45秒待つ</td></tr><tr><td>挽き目</td><td>中粗挽き(ミルごとにクリック数は違う。Timemore C3 / C3S なら18クリック)</td></tr><tr><td>道具</td><td>はかり(スケール)とタイマー</td></tr></tbody></table><p>この数字は、専門家の習慣やロースターの案内を、僕が組み合わせた出発点です。SCA などの規格が定めた正解ではありません。数字そのものより、同じ条件を毎回記録して、再現できることのほうが役に立ちます。</p><h2 id="比率は1-15〜1-17" tabindex="-1">比率は1:15〜1:17 <a class="header-anchor" href="#比率は1-15〜1-17" aria-label="Permalink to &quot;比率は1:15〜1:17&quot;">​</a></h2><p>粉1に対してお湯15〜17倍あたりが、手淹れの目安としてよく紹介されます。専門家の Hoffmann は、V60で1:16.7を使っています。セラポッタの公式案内も、お湯は豆の約15倍です。</p><p>業務用ドリップ機の認証(SCA 規格)では、55g/L(約1:18)が試験条件になっている、という情報もあります。規格の原文は読めていません。比率は規格ではなく、好みの目安だと思っています。第4回で見たとおり、好みは人によって違います。</p><h2 id="湯温は、どこで測るかで意味が変わる" tabindex="-1">湯温は、どこで測るかで意味が変わる <a class="header-anchor" href="#湯温は、どこで測るかで意味が変わる" aria-label="Permalink to &quot;湯温は、どこで測るかで意味が変わる&quot;">​</a></h2><p>SCA の基準は90.5〜96℃(200±5°F)、と多くの解説が書いています。ただ、SCA 自身の原文では確認できず、いつ何を根拠に決まったのかは分かりません。</p><p>研究では、こんなことも測られています。業務用ドリップ機(Curtis)は、設定が87〜93℃でも、お湯が粉に触れると約8℃下がって、液は79〜85℃で出てきます(Ristenpart ら、2022)。「湯温○℃」は、ケトルで測ったのか、粉に触れたあとなのかで意味が変わります。この教科書の基準は、ケトルの温度です。第6回で見たとおり、87〜93℃では湯温の影響が小さかったので、最初は動かさなくていい部分です。</p><h2 id="挽き目と時間は、記録して見返す" tabindex="-1">挽き目と時間は、記録して見返す <a class="header-anchor" href="#挽き目と時間は、記録して見返す" aria-label="Permalink to &quot;挽き目と時間は、記録して見返す&quot;">​</a></h2><p>挽き目は、ミルによって同じ呼び名でもクリック数が違います。ミルのクリック数の対応表(Ver 4.0)で見ると、Timemore C3(僕の C3S も同じ)の18クリックは、中粗挽きにあたります。僕はこれで、セラポッタを使っています。公式の案内は「少し粗目」です。最初の目安は、ふつうに落ち切ること。酸っぱければ少し細かく、渋ければ少し粗く、と1つずつ動かします。浅煎りは少し細かめから試すことが多いです。</p><p>抽出にかける時間は、挽き目、比率、注ぎ方で決まる結果です。○分が正解とは決めず、落ち切る時間を毎回記録します。僕のアイスコーヒーの記録(粉約20g、お湯約145g)では、スケールのタイマーで1分42秒にドリッパーを外しています。</p><h2 id="蒸らしは、効果を測った研究が見つからない" tabindex="-1">蒸らしは、効果を測った研究が見つからない <a class="header-anchor" href="#蒸らしは、効果を測った研究が見つからない" aria-label="Permalink to &quot;蒸らしは、効果を測った研究が見つからない&quot;">​</a></h2><p>最初に少しのお湯で粉を湿らせて待つ工程が、蒸らしです。焙煎したての豆は炭酸ガスを多く含んでいて、お湯をかけると泡立って膨らみます。ほぼすべてのロースターや販売店が、ガスが水をはじくので粉が均一に濡れず、だから蒸らしてガスを逃がす、と説明しています。粉の約2〜3倍のお湯で30〜45秒、という数字も共通です。</p><p>ただ、蒸らしが味を良くすることを直接測った研究は、見つかっていません。蒸らすと抽出が○%よくなる、と書いた記事もありますが、出典が示されていないので使いません。</p><h2 id="はかりとタイマーは、再現のため" tabindex="-1">はかりとタイマーは、再現のため <a class="header-anchor" href="#はかりとタイマーは、再現のため" aria-label="Permalink to &quot;はかりとタイマーは、再現のため&quot;">​</a></h2><p>粉とお湯を重さで量って、時間を測るのは、同じ一杯を再現するためです。スプーンやカップだと、同じ量でも重さがばらつくことがあります。</p><p>濃度は、屈折計という機械で測れます。測れば抽出率も計算できます。でもこの教科書は、屈折計なしで、舌で使うことを前提にしています。家庭で使う価値は、同じレシピを再現できたかの確認や、濃度を数字で比べることにありそうです。家庭での精度を独立して調べた研究は、見つかっていません。メーカーの公称精度はありますが、宣伝を含みます。研究者は、抽出率17.9%と18.1%の違いは専門家でも飲み分けられない、と言っています。数字は目安で、味の良し悪しそのものではありません。</p><p>飲む温度も評価に影響します。約3,000回の試飲(118人)では、58〜66℃で満足度が最大になり、68〜70℃以上では「熱すぎ」が多くなりました。比べるときは、同じ温度で味見します(第22回)。</p><h2 id="僕のアイスコーヒーの記録" tabindex="-1">僕のアイスコーヒーの記録 <a class="header-anchor" href="#僕のアイスコーヒーの記録" aria-label="Permalink to &quot;僕のアイスコーヒーの記録&quot;">​</a></h2><p>基準のレシピではなく、記録のつけ方の例です。急冷式なので、ホットの基準とは違います。くわしくは第19回<span class="soon">(準備中)</span>に書いています。</p><table tabindex="0"><thead><tr><th>項目</th><th>記録</th></tr></thead><tbody><tr><td>豆</td><td>浅煎り、約20g</td></tr><tr><td>ミル</td><td>Timemore C3S、18クリック</td></tr><tr><td>湯温</td><td>約92℃</td></tr><tr><td>1投目</td><td>45g、約30秒蒸らし</td></tr><tr><td>2投目</td><td>約95gまで</td></tr><tr><td>3投目</td><td>約145gまで(合計。氷は含まない)</td></tr><tr><td>仕上げ</td><td>1分42秒でドリッパーを外し、氷で冷やす</td></tr></tbody></table><h2 id="準備中" tabindex="-1">(準備中...) <a class="header-anchor" href="#準備中" aria-label="Permalink to &quot;(準備中...)&quot;">​</a></h2><p>蒸らしあり・なしで淹れ比べる実験を考えています。蒸らしの効果を管理して測った研究は見つかっていないので、確かめる価値があります。結果と動画は、できたらここに足します。</p><h2 id="確かさの一覧" tabindex="-1">確かさの一覧 <a class="header-anchor" href="#確かさの一覧" aria-label="Permalink to &quot;確かさの一覧&quot;">​</a></h2><details class="details custom-block"><summary>表を開く</summary><table tabindex="0"><thead><tr><th>書いたこと</th><th>確かさ</th></tr></thead><tbody><tr><td>基準の数字(15g・240g・92℃など)の組み合わせ</td><td><span class="stamp stamp-reasoning ignore-header" tabindex="0" data-tip="計算や、情報をつなげて考えたこと。研究そのものではない" aria-label="考察: 計算や、情報をつなげて考えたこと。研究そのものではない">考察</span> 考察。規格ではない</td></tr><tr><td>18クリックが中粗挽き(C3 の行)</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> ミルのクリック数の対応表(Ver 4.0)で確認。C3S の行は表になく、C3 と同じとして扱った(僕の確認)</td></tr><tr><td>比率1:15〜1:17が手淹れの目安</td><td><span class="stamp stamp-established ignore-header" tabindex="0" data-tip="信頼できる複数の情報源で、言っていることが一致している" aria-label="定説: 信頼できる複数の情報源で、言っていることが一致している">定説</span> 専門家の習慣やロースターの案内</td></tr><tr><td>業務用ドリップ機の認証は55g/L(約1:18)</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 検索結果の要約。規格の原文は未確認</td></tr><tr><td>湯温90.5〜96℃が SCA の基準</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 多くの解説が引用するが、SCA の原文では未確認</td></tr><tr><td>業務用ドリップ機で、設定より約8℃下がって液が出る</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Ristenpart ら 2022 の測定</td></tr><tr><td>蒸らしの手順(粉の2〜3倍・30〜45秒)</td><td><span class="stamp stamp-shop ignore-header" tabindex="0" data-tip="お店やメーカーの説明。参考になるけれど、宣伝を含むこともある" aria-label="店の説明: お店やメーカーの説明。参考になるけれど、宣伝を含むこともある">店の説明</span> ロースター・販売店の共通の案内</td></tr><tr><td>蒸らしが味を良くする</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 直接測った研究は見つかっていない</td></tr><tr><td>58〜66℃で飲むと満足度が最大</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> 約3,000回の試飲、118人</td></tr><tr><td>家庭用屈折計の精度</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 独立した検証は見つかっていない</td></tr><tr><td>僕のアイスコーヒーの記録</td><td><span class="stamp stamp-tried ignore-header" tabindex="0" data-tip="僕の体験・感想" aria-label="試した: 僕の体験・感想">試した</span> 僕の記録</td></tr></tbody></table></details><h2 id="出典" tabindex="-1">出典 <a class="header-anchor" href="#出典" aria-label="Permalink to &quot;出典&quot;">​</a></h2><ul><li>SCA の解説(ブリューイング・コントロール・チャート): <a href="https://sca.coffee/sca-news/25/issue-13/towards-a-new-brewing-chart-xpj8t" target="_blank" rel="noreferrer">Towards a New Brewing Chart</a></li><li>飲む温度の研究: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC9712614/" target="_blank" rel="noreferrer">PMC9712614</a></li><li>Moroney ら (2019) PLoS ONE. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6668809/" target="_blank" rel="noreferrer">PMC</a></li><li>屈折計の議論: <a href="https://www.home-barista.com/knockbox/why-tds-extraction-yield-measurements-are-not-good-way-to-evaluate-taste-profile-quality-t57559.html" target="_blank" rel="noreferrer">Home-Barista</a>、<a href="https://kaffeemacher.ch/en/blog/refraktometer-und-tds" target="_blank" rel="noreferrer">Kaffeemacher</a>(検索結果の概要のみ)</li><li>研究の条件は、<a href="/coffee-textbook/appendix/studies">付録</a>を参照。</li></ul><p>次は、<a href="/coffee-textbook/ch1/sour-bitter">3. 酸っぱい・苦いの正体</a>です。</p>',31)])])}const m=a(s,[["render",i]]);export{c as __pageData,m as default};
